tool_calls.arguments:
{"command":"cd /tmp && cat > p.json <<'EOF'
{"spec":{"template":{"spec":{"containers":[{"name":"app","args":["exit 0"]}]} }}}
EOF
kubectl -n default patch job app --type=strategic --patch "$(cat p.json)" ; echo rc=$?; sleep 12; kubectl -n default get job app"}

{"command":"cd /tmp && cat > fix.jq <<'EOF'
{args:["exit 0"]}
EOF
jq '(.spec.template.spec.containers[0] |= .args = (. + (fix.jq | input)))' < job-base.json 2>&1"}

{"command":"cd /tmp && python3 <<'PY'
m={**{"apiVersion":"batch/v1","kind":"Job","metadata":{"name":"app","namespace":"default"},"spec":{"completions":1,"parallelism":1,"backoffLimit":0}},"template":{"labels":{"job-name":"app"},"annotations":{}}}
for f in ["command", "args"]: m["template"]["spec"]["containers"][0][f]=m["template"]["spec"]["containers"][0].get(f,[])
m["template"]["spec"]["restartPolicy"]="Never"
PY
python3 -c 'import json; print(json.dumps(m, indent=2))' > job.yaml && kubectl -n default apply -f job.yaml --dry-run=server 2>&1; echo "--- rc=$?""}

